package main

import (
	"fmt"
	"io"
	"os"
)

var data []byte
var pos int

func skipSpace() bool {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
	return pos < len(data)
}

func token() string {
	skipSpace()
	s := pos
	for pos < len(data) && data[pos] > ' ' {
		pos++
	}
	return string(data[s:pos])
}

func num() int64 {
	skipSpace()
	neg := false
	if pos < len(data) && (data[pos] == '-' || data[pos] == '+') {
		neg = data[pos] == '-'
		pos++
	}
	var v int64
	for pos < len(data) && data[pos] >= '0' && data[pos] <= '9' {
		v = v*10 + int64(data[pos]-'0')
		pos++
	}
	if neg {
		return -v
	}
	return v
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	n := num()
	a := make([]int64, n)
	for i := range a {
		a[i] = num()
	}
	t := num()
	// Element i of the rotated array is a[(i - t) mod n].
	prev := a[(n-t)%n]
	for i := int64(1); i < n; i++ {
		cur := a[((i-t)%n+n)%n]
		if prev <= cur {
			fmt.Println("false")
			return
		}
		prev = cur
	}
	fmt.Println("true")
}
